fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    // Clone the input to build the output
    let mut result = word.clone();
    
    // Safe because the problem guarantees a non-empty input
    if result[0].is_ascii_lowercase() {
        // Replace a lowercase first letter with 'A'
        result[0] = 'A';
    }
    
    result
}

